import json

# Load demo 1 and add demo 2
json_file = "/home/ubuntu/runs/paper/qwen-hpl0-u1-turns/play/users/u000/system/state/workspace/programs/01a183b7-2105-70b5-ad17-efd135ab810f/task-0a6be289.json"

with open(json_file, 'r') as f:
    demo_data = json.load(f)

# Pattern 2: sep_row=5 (so upper is rows 0-4)
upper = demo_data[1]['input'][:5]  # rows 0-4
output_top = demo_data[1]['output']

# Test different column ranges
for cols_to_use in [9, 14]:
    # Create section with specified number of columns
    if cols_to_use >= len(upper[0]):
        test_upper = upper
    else:
        test_upper = [[col for col in row[:cols_to_use]] for row in upper]

    def transform_simple(grid):
        result = []
        for row in grid:
            new_row = []
            for cell in row:
                if cell == 4:
                    new_row.append(3)
                else:
                    new_row.append(4)
            result.append(new_row)
        return result

    result = transform_simple(test_upper)
    expected_cols = len(output_top[0])
    if len(result[0]) != expected_cols:
        print(f"Cols {cols_to_use}: shape mismatch, result {len(result[0])} cols, want {expected_cols}")
        continue

    match = all(result[r][c] == output_top[r][c] for r in range(len(output_top)) for c in range(len(output_top[0])))
    print(f"Cols {cols_to_use}: matches = {match}")

    # Find mismatches if any
    if not match:
        for r in range(len(output_top)):
            for c in range(len(output_top[0])):
                if result[r][c] != output_top[r][c]:
                    print(f"  Mismatch at ({r},{c}): got {result[r][c]}, want {output_top[r][c]}")

